export interface MailMessageLike {
    readonly messageId: string;
    readonly envelope: {
        from: string;
        to: string[];
    };
    toMime(): Buffer;
}
export interface MailTransportSendOptionsLike {
    signal: AbortSignal;
    idempotencyKey?: string;
    attempt: number;
}
export interface MailTransportResultLike {
    accepted?: string[];
    providerMessageId?: string;
    response?: string;
}
export interface MailTransportLike {
    send(message: MailMessageLike, options: MailTransportSendOptionsLike): Promise<MailTransportResultLike>;
    close?(): void | Promise<void>;
}
export interface MailTemplateRenderOptionsLike {
    readonly locale: string | undefined;
}
export type MailTemplateOutputLike = string | {
    html: string;
    text?: string;
};
export interface MailTemplateEngineLike {
    render(name: string, context: object, options: MailTemplateRenderOptionsLike): MailTemplateOutputLike | Promise<MailTemplateOutputLike>;
}
